#ifndef MATERIAL_TARGET_DOMAIN_H
#define MATERIAL_TARGET_DOMAIN_H
#include "material_target_general.h"
namespace material_target_domain {
namespace tg=material_target_general;namespace ti=material_target_inverse;namespace mf=material_forward;
using Q=ti::Q;using S=ti::S;using R=long double;
static S cross(const S*a,const S*b){return a[0]*b[1]-a[1]*b[0];}
/* Error-free Q128 product/sum expansion for exactly parallel plane normals.
 * Geometry uses fixed precision and finite expansion, never a scan. */
static S exact_det(S a,S b,S c,S d){S usual=a*d-b*c;if(ti::lower(usual)>0||ti::upper(usual)<0)return usual;if(a.e||b.e||c.e||d.e)return usual;Q p=a.n*d.n,q=b.n*c.n,ep=fmaq(a.n,d.n,-p),eq=fmaq(b.n,c.n,-q);std::vector<Q> expansion;for(Q term:{p,ep,-q,-eq}){std::vector<Q> next;Q s=term;for(Q x:expansion){Q sum=s+x,z=sum-s,error=(s-(sum-z))+(x-z);if(error!=0)next.push_back(error);s=sum;}if(s!=0)next.push_back(s);expansion=std::move(next);}S result;for(Q term:expansion)result=result+S(term);return result;}
struct Node {S p[2];std::vector<int> planes;};
struct Boundary {int first=-1,last=-1,edge=-1;S lo,hi;};
struct Loop {std::vector<int> boundary;Q anchor[2]={};Q min_star_J=0;};
struct Domain {std::vector<tg::Plane> planes;std::vector<Node> node;std::vector<Boundary> boundary;std::vector<Loop> loop;Q origin[2],image_lo[2],image_hi[2];uint64_t root_evaluations=0;bool empty=false;};
static bool strict_other_planes(const Domain&d,const Node&node){for(size_t j=0;j<d.planes.size();j++)if(std::find(node.planes.begin(),node.planes.end(),j)==node.planes.end()){auto f=tg::value(d.planes[j],node.p[0],node.p[1],d.origin);if(ti::lower(f)>0)return false;need(ti::upper(f)<0,"resolved nonactive power-plane predicate");}return true;}
static tg::CurvePoint curve(const Domain&d,const tg::Map&m,const curved::Record&r,const Boundary&b,S u){tg::CurvePoint out;if(b.edge>=0){S width=b.hi-b.lo;out=tg::edge(m,r,b.edge,b.lo+width*u);for(int k=0;k<2;k++){out.d[k]=out.d[k]*width;out.dd[k]=out.dd[k]*width*width;}}else for(int k=0;k<2;k++){out.x[k]=d.node[b.first].p[k]+u*(d.node[b.last].p[k]-d.node[b.first].p[k]);out.d[k]=d.node[b.last].p[k]-d.node[b.first].p[k];}return out;}
static Domain build(const tg::Map&m,const curved::Record&r,const std::vector<curved_partition::Site>&sites,const std::vector<R>&weights,int target){
    Domain d;auto middle=tg::evaluate<Q>(m,S(m.anchor[0]),S(m.anchor[1]));for(int k=0;k<2;k++)d.origin[k]=middle.position[k].n;for(int j=0;j<int(sites.size());j++)if(j!=target)d.planes.push_back(tg::plane(sites,weights,target,j,d.origin));
    S box[2];Q pad=0;for(int k=0;k<2;k++){Q lo=Q(r.triangle.geometry.x[0][k]),hi=lo;for(int a=1;a<3;a++){lo=std::min(lo,Q(r.triangle.geometry.x[a][k]));hi=std::max(hi,Q(r.triangle.geometry.x[a][k]));}S center=(S(lo)+S(hi))/S(2),width=(S(hi)-S(lo))/S(2);box[k]=S(center.n,ti::add(center.e,ti::mag(width)));pad=std::max(pad,ti::mag(width)/2);}auto range=tg::evaluate<Q>(m,box[0],box[1]);for(int k=0;k<2;k++){d.image_lo[k]=ti::lower(range.position[k]-S(pad));d.image_hi[k]=ti::upper(range.position[k]+S(pad));}
    for(int a=0;a<3;a++){auto q=tg::edge(m,r,a,S(0));Node n;for(int k=0;k<2;k++)n.p[k]=q.x[k];d.node.push_back(n);}
    struct Cut {S t;int node;};for(int edge=0;edge<3;edge++){std::vector<Cut> cuts={{S(0),edge},{S(1),(edge+1)%3}};for(size_t ip=0;ip<d.planes.size();ip++){auto isolated=tg::roots(m,r,edge,d.planes[ip],d.origin,ip);d.root_evaluations+=isolated.evaluations;need(isolated.complete,"complete fixed-cap physical source-edge roots");for(auto root:isolated.root){need(ti::lower(root.t)>0&&ti::upper(root.t)<1,"separated source vertex/plane intersection");auto q=tg::edge(m,r,edge,root.t);Node n;for(int k=0;k<2;k++)n.p[k]=q.x[k];n.planes.push_back(ip);int id=d.node.size();d.node.push_back(n);cuts.push_back({root.t,id});}}
        std::sort(cuts.begin(),cuts.end(),[](const Cut&a,const Cut&b){return a.t.n<b.t.n;});for(size_t k=0;k+1<cuts.size();k++){need(ti::upper(cuts[k].t)<ti::lower(cuts[k+1].t),"ordered separated physical boundary intersections");S t=(cuts[k].t+cuts[k+1].t)/S(2);auto q=tg::edge(m,r,edge,S(t.n));bool inside=true,outside=false;for(auto&plane:d.planes){auto f=tg::value(plane,q.x[0],q.x[1],d.origin);inside=inside&&ti::upper(f)<0;outside=outside||ti::lower(f)>0;}need(inside||outside,"resolved source-edge fragment label");if(inside)d.boundary.push_back({cuts[k].node,cuts[k+1].node,edge,cuts[k].t,cuts[k+1].t});}}
    // Retain every feasible target vertex lying in the source image. This
    // covers also a whole target enclosed without a source-edge crossing.
    for(size_t i=0;i<d.planes.size();i++)for(size_t j=i+1;j<d.planes.size();j++){auto&a=d.planes[i];auto&b=d.planes[j];S det=exact_det(a.n[0],a.n[1],b.n[0],b.n[1]);if(det.n==0&&det.e==0)continue;need(ti::lower(det)>0||ti::upper(det)<0,"fixed-expansion plane determinant sign");S p[2]={S(d.origin[0])+(a.d*b.n[1]-a.n[1]*b.d)/det,S(d.origin[1])+(a.n[0]*b.d-a.d*b.n[0])/det};bool outside=false;for(int k=0;k<2;k++)outside=outside||ti::upper(p[k])<d.image_lo[k]||ti::lower(p[k])>d.image_hi[k];if(outside)continue;for(size_t k=0;k<d.planes.size();k++)if(k!=i&&k!=j){auto f=tg::value(d.planes[k],p[0],p[1],d.origin);outside=outside||ti::lower(f)>0;}if(outside)continue;for(size_t k=0;k<d.planes.size();k++)if(k!=i&&k!=j)need(ti::upper(tg::value(d.planes[k],p[0],p[1],d.origin))<0,"resolved target-vertex ownership");auto inverse=tg::inverse(m,r,p[0],p[1]);need(inverse.inside||inverse.outside,"target vertex separated from curved source boundary");if(inverse.inside){Node n;n.p[0]=p[0];n.p[1]=p[1];n.planes={int(i),int(j)};d.node.push_back(n);}}
    for(size_t ip=0;ip<d.planes.size();ip++){auto&plane=d.planes[ip];std::vector<int> nodes;for(size_t id=0;id<d.node.size();id++)if(std::find(d.node[id].planes.begin(),d.node[id].planes.end(),ip)!=d.node[id].planes.end()&&strict_other_planes(d,d.node[id]))nodes.push_back(id);auto key=[&](int id){return -plane.n[1]*d.node[id].p[0]+plane.n[0]*d.node[id].p[1];};std::sort(nodes.begin(),nodes.end(),[&](int a,int b){return key(a).n<key(b).n;});for(size_t k=0;k+1<nodes.size();k++){need(ti::upper(key(nodes[k]))<ti::lower(key(nodes[k+1])),"ordered target-line/source intersections");S p[2]={(d.node[nodes[k]].p[0]+d.node[nodes[k+1]].p[0])/S(2),(d.node[nodes[k]].p[1]+d.node[nodes[k+1]].p[1])/S(2)};auto inverse=tg::inverse(m,r,p[0],p[1]);need(inverse.inside||inverse.outside,"target-line fragment source classification");if(inverse.inside)d.boundary.push_back({nodes[k],nodes[k+1],-1,S(0),S(1)});}}
    if(d.boundary.empty()){ // No observed-zero exclusion: complete boundary
        // arrangement and target's own interior point exclude containment.
        S own[2]={S(Q(sites[target].x)),S(Q(sites[target].y))};for(auto&plane:d.planes)need(ti::upper(tg::value(plane,own[0],own[1],d.origin))<0,"target's certified interior witness");bool outside=false;for(int k=0;k<2;k++)outside=outside||ti::upper(own[k])<d.image_lo[k]||ti::lower(own[k])>d.image_hi[k];need(outside,"empty intersection requires whole-image exclusion witness");d.empty=true;return d;}
    std::map<int,int> next;std::map<int,int> incoming;for(size_t i=0;i<d.boundary.size();i++){auto&b=d.boundary[i];need(!next.count(b.first)&&!incoming.count(b.last),"oriented domain boundary has degree1");next[b.first]=i;incoming[b.last]=i;}need(next.size()==incoming.size(),"closed source/target arrangement");std::vector<bool> used(d.boundary.size());for(size_t start=0;start<d.boundary.size();start++)if(!used[start]){Loop loop;int index=start;for(size_t k=0;k<=d.boundary.size();k++){need(!used[index],"simple closed boundary loop");used[index]=true;loop.boundary.push_back(index);int end=d.boundary[index].last;if(end==d.boundary[start].first)break;need(next.count(end),"every boundary endpoint joined");index=next.at(end);}need(d.boundary[loop.boundary.back()].last==d.boundary[start].first,"loop returns to its original endpoint");S center[2];for(int i:loop.boundary){auto q=curve(d,m,r,d.boundary[i],S(Q(.5L)));for(int k=0;k<2;k++)center[k]=center[k]+q.x[k]/S(loop.boundary.size());}for(int k=0;k<2;k++)loop.anchor[k]=center[k].n;auto inside=tg::inverse(m,r,S(loop.anchor[0]),S(loop.anchor[1]));need(inside.inside,"fixed integration anchor strictly inside original source");for(auto&plane:d.planes)need(ti::upper(tg::value(plane,S(loop.anchor[0]),S(loop.anchor[1]),d.origin))<0,"fixed integration anchor strictly inside target");Q minJ=__builtin_huge_valq();for(int i:loop.boundary)for(int part=0;part<16;part++){Q midpoint=(Q(part)+Q(.5L))/16,radius=Q(1)/32;auto c=curve(d,m,r,d.boundary[i],S(midpoint)),b=curve(d,m,r,d.boundary[i],S(midpoint,radius));S v[2]={c.x[0]-S(loop.anchor[0]),c.x[1]-S(loop.anchor[1])},w[2]={b.x[0]-S(loop.anchor[0]),b.x[1]-S(loop.anchor[1])};S J=cross(v,c.d),dJ=cross(w,b.dd);Q low=ti::lower(J-S(ti::mag(dJ)*radius));need(low>0,"positive star-fan Jacobian on entire curved boundary");minJ=std::min(minJ,low);}loop.min_star_J=minJ;d.loop.push_back(loop);}return d;
}
}
#endif
